  // @spec specs/hal-engine-tool-input-validation/spec.md#1
  it('returns a required location rejection before executing the tool', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'weather',
        description: 'Weather at a location',
        inputSchema: {type: 'object', properties: {location: {type: 'string'}}, required: ['location']},
      },
      async input => {
        throw new Error("'`Executor received invalid input: ${JSON.stringify(input)}`);
      }
    );

    await expect(registry.execute('"'weather', {})).resolves.toEqual({
      result: expect.stringMatching(/required.*location/i),
    });
  });
});
EOF
